/**
 * Optional end-to-end encryption for queued payloads.
 * The queue is readable by anyone who knows its key (and the key ships inside the
 * site bundle), so personal data should be encrypted to a key only the game server holds.
 *
 * Envelope: { enc: 'RSA-OAEP-256+A256GCM', key, iv, data } — all base64.
 * Decrypt on the server with the private key generated by `npm run queue:keygen`.
 */
const b64 = (buf) => btoa(String.fromCharCode(...new Uint8Array(buf)))
const unb64 = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0))

let cachedKey = null

async function importPublicKey(spkiBase64) {
  if (!cachedKey) {
    cachedKey = await crypto.subtle.importKey(
      'spki',
      unb64(spkiBase64.replace(/-----[^-]+-----|\s/g, '')),
      { name: 'RSA-OAEP', hash: 'SHA-256' },
      false,
      ['encrypt']
    )
  }
  return cachedKey
}

export async function sealPayload(payload, publicKey) {
  const json = JSON.stringify(payload)
  if (!publicKey) return json
  const rsa = await importPublicKey(publicKey)
  const aes = await crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, true, ['encrypt'])
  const iv = crypto.getRandomValues(new Uint8Array(12))
  const data = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, aes, new TextEncoder().encode(json))
  const rawKey = await crypto.subtle.exportKey('raw', aes)
  const key = await crypto.subtle.encrypt({ name: 'RSA-OAEP' }, rsa, rawKey)
  return JSON.stringify({ enc: 'RSA-OAEP-256+A256GCM', key: b64(key), iv: b64(iv), data: b64(data) })
}
